def detect_wellness_trend(stress, sleep, energy):
    # Milestone 5 rule; do not change without updating boundary tests.
    return ("Elevated wellness trend detected"
            if stress >= 7 and sleep <= 5 and energy <= 5
            else "No elevated wellness trend detected")

def detect_weekly_pattern(stress_scores, sleep_scores, energy_scores):
    return ("Elevated weekly wellness trend detected"
            if stress_scores[-1]-stress_scores[0] >= 3
            and sleep_scores[-1]-sleep_scores[0] <= -3
            and energy_scores[-1]-energy_scores[0] <= -3
            else "No elevated weekly wellness trend detected")

def get_cloud_result(stress, sleep, energy):
    if not API_URL:
        return None, "Cloud API not configured; local fallback used.", None
    try:
        start=time.perf_counter()
        r=requests.post(API_URL,json={"stress":stress,"sleep":sleep,"energy":energy},timeout=10)
        r.raise_for_status()
        result=r.json()
        trend=result.get("trend_result")
        if trend not in {"Elevated wellness trend detected",
                         "No elevated wellness trend detected"}:
            raise ValueError("Unexpected cloud trend result")
        return trend, str(result.get("processing_layer","Google Colab")),time.perf_counter()-start
    except (requests.RequestException,ValueError,TypeError):
        return None,"Cloud unavailable or invalid response; local fallback used.",None

def load_checkins():
    """Read only this visitor's temporary, in-memory demonstration records."""
    return list(st.session_state.get("rp_private_demo_checkins", []))


def save_checkin(row):
    """Keep fictional responses in the current browser session; never write CSV."""
    if "rp_private_demo_checkins" not in st.session_state:
        st.session_state["rp_private_demo_checkins"] = []
    st.session_state["rp_private_demo_checkins"].append(dict(row))


def suggestions(stress,sleep,energy,workload,mood,supported,prepared,previous,outside="Prefer not to say"):
    ideas=[]
    if stress>=7: ideas.append(("🫧 Reset briefly","If safe and practical, try a short pause, slow breathing, or a quiet moment between tasks."))
    if sleep<=5: ideas.append(("🌙 Prioritize rest","When off duty, consider a consistent wind-down routine and allowing time for sleep."))
    if energy<=5: ideas.append(("💧 Recharge","Consider water, a meal or snack, and a short rest break when circumstances allow."))
    if workload>=7: ideas.append(("📋 Review workload","If possible, discuss priorities or workload support with an appropriate supervisor."))
    if mood<=4: ideas.append(("💗 Check in with yourself","Consider a pleasant activity or talking with someone you trust."))
    if supported<=4: ideas.append(("🤝 Connect","You might reach out to a trusted colleague, peer support contact, or employee assistance resource."))
    if prepared<=4: ideas.append(("🧭 Ask for support","Consider discussing preparation or support needs with a trusted supervisor before your shift."))
    if previous in ("Moderately","A lot"): ideas.append(("🫶 After a difficult shift","Consider a confidential peer-support or employee assistance resource if an incident is still affecting you."))
    if outside in ("Yes", "A little"):
        ideas.append(("💗 Support beyond work", "Personal concerns matter too. Consider journaling, a trusted person, or an appropriate confidential counseling resource."))
    if not ideas: ideas=[("🌼 Keep checking in","Continue noticing your wellness patterns and taking breaks when possible."),
                         ("🤝 Stay connected","Keep trusted people and support resources within reach.")]
    return ideas[:5]

