    st.markdown("#### 🌬️ Breathe With Me")
    st.write("Press Start for gentle spoken and visual cues. Breathe in for four seconds and out for six; no breath holding. Stop anytime if uncomfortable.")
    components.html(r'''<div style="font-family:system-ui;background:#172747;border:1px solid #45608b;border-radius:18px;padding:18px;text-align:center;color:#fff">
      <div id="cue" aria-live="polite" style="font-size:26px;font-weight:700;color:#91cbff">Ready when you are</div>
      <div id="counter" style="font-size:55px;font-weight:800;margin:12px">60</div>
      <div style="margin-bottom:14px;color:#d5e0ff">Gentle breathing • optional voice cues</div>
      <label>Session <select id="duration" style="background:#26385d;color:white;padding:7px;border-radius:8px"><option value="30">30 seconds</option><option value="60" selected>60 seconds</option><option value="120">2 minutes</option></select></label>
      <label style="margin-left:12px"><input id="voice" type="checkbox" checked> Spoken cues</label>
      <div style="margin-top:15px"><button onclick="start()">▶ Start</button><button onclick="pause()">⏸ Pause</button><button onclick="reset()">↺ Reset</button></div>
      <div id="hint" style="font-size:13px;color:#cad7ee;margin-top:12px">Voice uses your browser's built-in speech feature when supported.</div>
    </div>
    <style>button{background:#9c72ee;color:white;border:0;border-radius:9px;padding:10px 14px;margin:4px;cursor:pointer;font-weight:650}button:hover{background:#e36bb6}</style>
    <script>
    let remaining=60,elapsed=0,handle=null,running=false,spoken='';
    const counter=document.getElementById('counter'),cue=document.getElementById('cue'),duration=document.getElementById('duration');
    function say(t){if(document.getElementById('voice').checked && 'speechSynthesis' in window){speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(t);u.rate=.9;speechSynthesis.speak(u)}}
    function display(){counter.textContent=remaining; if(remaining<=0){cue.textContent='You took a moment for yourself 💗';if(spoken!=='complete'){say('Session complete. Stay safe. You matter.');spoken='complete'}return;}let phase=elapsed%10<4?'Breathe in':'Breathe out';cue.textContent=phase;if(phase!==spoken){say(phase);spoken=phase}}
    function tick(){remaining--;elapsed++;display();if(remaining<=0)pause()}
    function start(){if(running)return;if(remaining<=0){reset()}running=true;display();handle=setInterval(tick,1000)}
    function pause(){running=false;if(handle!==null)clearInterval(handle);handle=null;if('speechSynthesis' in window)speechSynthesis.cancel()}
    function reset(){pause();remaining=Number(duration.value);elapsed=0;spoken='';counter.textContent=remaining;cue.textContent='Ready when you are'}
    duration.addEventListener('change',reset);
    window.addEventListener('pagehide',pause);
    </script>''',height=335)
